export const PLANT_KINGDOM = [
  // ---- MCQ ----
  { id: 'pk-1', type: 'mcq', question: 'Kingdom Plantae, as understood in classical plant classification, includes:', options: ['Only flowering plants', 'Algae, bryophytes, pteridophytes, gymnosperms, and angiosperms', 'Only bacteria and fungi', 'Only mosses and ferns'], correctIndex: 1, explanation: 'Plantae broadly spans algae through angiosperms in this classification scheme.', difficulty: 'easy' },
  { id: 'pk-2', type: 'mcq', question: 'Algae are primarily classified into three major classes based on the type of pigment present, namely:', options: ['Chlorophyceae, Phaeophyceae, Rhodophyceae', 'Bryophyta, Pteridophyta, Gymnospermae', 'Thallophyta, Cryptogamae, Phanerogamae', 'Monocot, Dicot, Gymnosperm'], correctIndex: 0, explanation: 'Chlorophyceae (green), Phaeophyceae (brown), and Rhodophyceae (red) algae are classified largely by pigmentation.', difficulty: 'medium' },
  { id: 'pk-3', type: 'mcq', question: 'Members of Chlorophyceae (green algae) are characterised by the presence of pigments:', options: ['Chlorophyll a and b, stored food as starch', 'Only fucoxanthin', 'Only phycoerythrin', 'Chlorophyll d only'], correctIndex: 0, explanation: 'Green algae have chlorophyll a and b as dominant pigments and store food as starch.', difficulty: 'medium' },
  { id: 'pk-4', type: 'mcq', question: 'Brown algae (Phaeophyceae) owe their colour mainly to the pigment:', options: ['Chlorophyll a only', 'Fucoxanthin', 'Phycoerythrin', 'Anthocyanin'], correctIndex: 1, explanation: 'Fucoxanthin, a brown pigment, dominates in Phaeophyceae, masking other pigments.', difficulty: 'medium' },
  { id: 'pk-5', type: 'mcq', question: 'Red algae (Rhodophyceae) derive their characteristic colour from the pigment:', options: ['Phycoerythrin', 'Chlorophyll b', 'Fucoxanthin', 'Xanthophyll'], correctIndex: 0, explanation: 'Phycoerythrin, a red pigment, gives Rhodophyceae members their characteristic colour.', difficulty: 'medium' },
  { id: 'pk-6', type: 'mcq', question: 'Bryophytes are often called the "amphibians of the plant kingdom" because:', options: ['They live only in water', 'They can live in soil but are dependent on water for sexual reproduction', 'They have no roots or leaves at all', 'They are the largest plants on Earth'], correctIndex: 1, explanation: 'Bryophytes grow on land but require water for the motile male gametes to reach the female gametes, similar to amphibians needing water for reproduction.', difficulty: 'medium' },
  { id: 'pk-7', type: 'mcq', question: 'The dominant, photosynthetic phase in the life cycle of a typical bryophyte is the:', options: ['Diploid sporophyte', 'Haploid gametophyte', 'Diploid zygote only', 'Triploid endosperm'], correctIndex: 1, explanation: 'In bryophytes, the haploid gametophyte is the dominant, independent, photosynthetic phase.', difficulty: 'medium' },
  { id: 'pk-8', type: 'mcq', question: 'The main classes of Bryophyta are:', options: ['Liverworts, Mosses, and Hornworts', 'Algae, Fungi, and Lichens', 'Ferns, Cycads, and Conifers', 'Monocots and Dicots'], correctIndex: 0, explanation: 'Liverworts, mosses, and hornworts are the three main classes within Bryophyta.', difficulty: 'medium' },
  { id: 'pk-9', type: 'mcq', question: 'In pteridophytes, the dominant and independent phase of the life cycle is the:', options: ['Haploid gametophyte', 'Diploid sporophyte', 'Endosperm', 'Pollen grain'], correctIndex: 1, explanation: 'Unlike bryophytes, pteridophytes have a dominant, independent sporophyte, with a much smaller, often short-lived gametophyte.', difficulty: 'medium' },
  { id: 'pk-10', type: 'mcq', question: 'Ferns and related plants like Selaginella and Equisetum belong to which plant group?', options: ['Bryophyta', 'Pteridophyta', 'Gymnospermae', 'Angiospermae'], correctIndex: 1, explanation: 'Ferns, Selaginella, and Equisetum are classic examples of pteridophytes.', difficulty: 'easy' },
  { id: 'pk-11', type: 'mcq', question: 'Pteridophytes are also referred to as the first true "vascular plants" because they possess:', options: ['No roots, stems, or leaves at all', 'A well-developed xylem and phloem for conduction', 'Only rhizoids for absorption', 'No true photosynthetic tissue'], correctIndex: 1, explanation: 'Pteridophytes are the earliest plant group to develop true vascular tissue (xylem/phloem).', difficulty: 'medium' },
  { id: 'pk-12', type: 'mcq', question: 'The condition in which a plant produces two different types of spores (microspores and megaspores) is called:', options: ['Homospory', 'Heterospory', 'Isogamy', 'Oogamy'], correctIndex: 1, explanation: 'Heterospory refers to producing two morphologically distinct spore types, seen in some pteridophytes (e.g., Selaginella) and all seed plants.', difficulty: 'medium' },
  { id: 'pk-13', type: 'mcq', question: 'Heterospory is considered evolutionarily significant mainly because it is a precursor to the evolution of:', options: ['Chlorophyll', 'The seed habit', 'Cell walls', 'Photosynthesis'], correctIndex: 1, explanation: 'Heterospory, especially retention of the megaspore within the megasporangium, is seen as a key evolutionary step toward the seed habit.', difficulty: 'medium' },
  { id: 'pk-14', type: 'mcq', question: 'Gymnosperms are named for having:', options: ['No seeds at all', 'Naked seeds not enclosed within a fruit/ovary wall', 'Seeds fully enclosed within a fruit', 'Only spores, never seeds'], correctIndex: 1, explanation: "'Gymnosperm' literally means 'naked seed' — the ovules/seeds are not enclosed by an ovary wall.", difficulty: 'easy' },
  { id: 'pk-15', type: 'mcq', question: 'Common examples of gymnosperms include:', options: ['Rose and Hibiscus', 'Pinus, Cycas, and Cedrus', 'Rice and Wheat', 'Mango and Banana'], correctIndex: 1, explanation: 'Pinus, Cycas, and Cedrus are classic gymnosperm examples (conifers/cycads).', difficulty: 'easy' },
  { id: 'pk-16', type: 'mcq', question: 'Angiosperms are distinguished from gymnosperms mainly by having:', options: ['No flowers at all', 'Seeds enclosed within a fruit, developing from a fertilised ovary', 'No vascular tissue', 'Only asexual reproduction'], correctIndex: 1, explanation: "Angiosperms ('covered seed') develop seeds enclosed within a fruit, unlike gymnosperms' naked seeds.", difficulty: 'easy' },
  { id: 'pk-17', type: 'mcq', question: 'The unique reproductive event in angiosperms, in which one male gamete fuses with the egg and another fuses with the polar nuclei, is called:', options: ['Simple fertilisation', 'Double fertilisation', 'Self-pollination only', 'Parthenogenesis'], correctIndex: 1, explanation: 'Double fertilisation, unique to angiosperms, produces both the zygote and the triploid endosperm.', difficulty: 'medium' },
  { id: 'pk-18', type: 'mcq', question: 'Angiosperms are broadly divided into two classes based on the number of cotyledons in the seed, namely:', options: ['Bryophytes and Pteridophytes', 'Monocotyledonae and Dicotyledonae', 'Chlorophyceae and Rhodophyceae', 'Gymnosperms and Angiosperms'], correctIndex: 1, explanation: 'Angiosperms are classified as monocots (one cotyledon) or dicots (two cotyledons).', difficulty: 'easy' },
  { id: 'pk-19', type: 'mcq', question: 'The alternation of generations in plants refers to the alternation between:', options: ['Two haploid phases only', 'A haploid gametophytic phase and a diploid sporophytic phase', 'Two diploid phases only', 'Vegetative and reproductive phases with no ploidy change'], correctIndex: 1, explanation: 'Plant life cycles alternate between a haploid, gamete-producing gametophyte and a diploid, spore-producing sporophyte.', difficulty: 'medium' },
  { id: 'pk-20', type: 'mcq', question: 'A life cycle pattern in which the dominant phase is haploid, with the zygote being the only diploid stage, is called:', options: ['Diplontic life cycle', 'Haplontic life cycle', 'Haplo-diplontic life cycle', 'Triploid life cycle'], correctIndex: 1, explanation: 'In a haplontic life cycle, the dominant multicellular phase is haploid; the zygote is the sole diploid stage, undergoing meiosis immediately.', difficulty: 'medium' },
  { id: 'pk-21', type: 'mcq', question: 'A life cycle pattern in which the diploid sporophyte is the dominant, independent phase (as in humans and most seed plants) is called:', options: ['Haplontic', 'Diplontic', 'Haplo-diplontic', 'Isomorphic'], correctIndex: 1, explanation: 'In a diplontic life cycle, the diploid phase dominates; meiosis occurs just before gamete formation.', difficulty: 'medium' },
  { id: 'pk-22', type: 'mcq', question: 'A life cycle pattern showing both multicellular haploid and multicellular diploid stages (as in bryophytes and pteridophytes) is called:', options: ['Haplontic', 'Diplontic', 'Haplo-diplontic', 'Non-alternating'], correctIndex: 2, explanation: 'Haplo-diplontic life cycles show alternating multicellular haploid (gametophyte) and diploid (sporophyte) generations.', difficulty: 'medium' },
  { id: 'pk-23', type: 'mcq', question: 'Which group of the plant kingdom is generally considered aquatic (mostly) and simplest in body organisation, often called "simple thalloid" plants?', options: ['Angiosperms', 'Algae', 'Gymnosperms', 'Bryophyta only'], correctIndex: 1, explanation: 'Algae are typically simple, mostly aquatic organisms with a relatively undifferentiated thalloid body.', difficulty: 'easy' },
  { id: 'pk-24', type: 'mcq', question: 'A major economic importance of red and brown algae is that they are harvested for:', options: ['Timber production', 'Agar and algin production', 'Cotton fibre', 'Rubber latex'], correctIndex: 1, explanation: 'Agar (from red algae like Gelidium/Gracilaria) and algin (from brown algae) are commercially important products.', difficulty: 'medium' },
  { id: 'pk-25', type: 'mcq', question: 'Chlorella and Spirulina, algae rich in protein, are cultured commercially mainly as a source of:', options: ['Fossil fuels', 'Single-cell protein for food supplements', 'Building material', 'Synthetic fibre'], correctIndex: 1, explanation: 'Chlorella and Spirulina are cultivated as single-cell protein sources for food supplementation.', difficulty: 'medium' },
  { id: 'pk-26', type: 'mcq', question: 'Liverworts typically grow in moist, shady habitats and have a body that is:', options: ['A well-differentiated root-stem-leaf system', 'A flattened, thalloid form', 'Composed entirely of woody tissue', 'Completely submerged and never on land'], correctIndex: 1, explanation: 'Liverworts have a simple, dorsiventrally flattened thalloid body.', difficulty: 'medium' },
  { id: 'pk-27', type: 'mcq', question: 'Mosses, unlike liverworts, have a more differentiated plant body consisting of:', options: ['A stem-like axis with leaf-like appendages', 'A single-celled thallus only', 'No gametophyte generation at all', 'A fruit and seed'], correctIndex: 0, explanation: 'Mosses have a more organised body with an upright, "leafy" gametophyte compared to liverworts.', difficulty: 'medium' },
  { id: 'pk-28', type: 'mcq', question: 'The "protonema" stage, a green, branched, filamentous structure, is a characteristic developmental stage seen in which group?', options: ['Algae', 'Mosses', 'Ferns', 'Gymnosperms'], correctIndex: 1, explanation: 'Mosses have a protonema stage — a filamentous, branched structure that develops from a germinating spore before the leafy gametophyte forms.', difficulty: 'medium' },
  { id: 'pk-29', type: 'mcq', question: 'In pteridophytes, the underground/underwater and inconspicuous gametophyte is called the:', options: ['Sporophyte', 'Prothallus', 'Endosperm', 'Zygote'], correctIndex: 1, explanation: "The pteridophyte gametophyte, often small and inconspicuous, is called the prothallus.", difficulty: 'medium' },
  { id: 'pk-30', type: 'mcq', question: 'Selaginella is a notable pteridophyte example because it exhibits:', options: ['Homospory', 'Heterospory', 'No spore formation at all', 'Fruit formation'], correctIndex: 1, explanation: 'Selaginella is a classic heterosporous pteridophyte, producing both microspores and megaspores.', difficulty: 'medium' },
  { id: 'pk-31', type: 'mcq', question: 'In gymnosperms, male and female gametophytes are usually reduced and dependent on the:', options: ['Independent free-living stage', 'Sporophyte for nutrition', 'Soil directly', 'Water for gamete transfer exclusively'], correctIndex: 1, explanation: 'Gymnosperm gametophytes are highly reduced and remain nutritionally dependent on the sporophyte.', difficulty: 'medium' },
  { id: 'pk-32', type: 'mcq', question: 'Fertilisation in gymnosperms typically does not require external water because male gametes are usually transferred via:', options: ['Swimming through rainwater', 'A pollen tube', 'Wind-dispersed spores only', 'Insect pollinators exclusively'], correctIndex: 1, explanation: 'A pollen tube delivers non-motile male gametes directly to the egg, freeing gymnosperms (mostly) from needing external water for fertilisation.', difficulty: 'medium' },
  { id: 'pk-33', type: 'mcq', question: 'In flowering plants, the male gametophyte is represented by the:', options: ['Ovule', 'Pollen grain', 'Embryo sac', 'Endosperm'], correctIndex: 1, explanation: 'The pollen grain is the (reduced) male gametophyte in angiosperms.', difficulty: 'easy' },
  { id: 'pk-34', type: 'mcq', question: 'In flowering plants, the female gametophyte is represented by the:', options: ['Pollen grain', 'Anther', 'Embryo sac (megagametophyte)', 'Stamen'], correctIndex: 2, explanation: 'The embryo sac, found within the ovule, is the reduced female gametophyte in angiosperms.', difficulty: 'medium' },
  { id: 'pk-35', type: 'mcq', question: 'The endosperm formed after double fertilisation in angiosperms is typically:', options: ['Haploid', 'Diploid', 'Triploid', 'Tetraploid'], correctIndex: 2, explanation: 'Fusion of one male gamete with two polar nuclei produces the triploid (3n) endosperm.', difficulty: 'medium' },
  { id: 'pk-36', type: 'mcq', question: 'Which of the following is a key adaptive advantage of the seed habit over spore dispersal?', options: ['Seeds are always smaller than spores', 'Seeds contain stored food and a protective coat, aiding survival and dispersal', 'Seeds cannot survive dry conditions at all', 'Seeds require constant external water for germination'], correctIndex: 1, explanation: 'Seeds package an embryo with stored nutrition and protection, greatly aiding survival compared to bare spores.', difficulty: 'medium' },
  { id: 'pk-37', type: 'mcq', question: 'Cycas, a gymnosperm, is notable for having:', options: ['Only microscopic, single-celled bodies', 'Large, compound leaves and being dioecious (separate male and female plants)', 'Flowers with both stamens and carpels', 'Fruits enclosing its seeds'], correctIndex: 1, explanation: 'Cycas has large pinnate leaves and separate male and female plants (dioecious).', difficulty: 'medium' },
  { id: 'pk-38', type: 'mcq', question: 'The vascular tissue system, essential for water and nutrient transport, first evolved prominently in which plant group?', options: ['Algae', 'Bryophytes', 'Pteridophytes', 'None of the plant groups have vascular tissue'], correctIndex: 2, explanation: 'Pteridophytes are the earliest group to show well-developed vascular tissue.', difficulty: 'medium' },
  { id: 'pk-39', type: 'mcq', question: 'A key reason bryophytes generally remain small and low-growing is:', options: ['Lack of true vascular tissue for efficient water/nutrient transport', 'Excess vascular tissue causing overgrowth', 'Absence of any photosynthetic pigment', 'Presence of a fruit that weighs them down'], correctIndex: 0, explanation: 'Without efficient vascular tissue, bryophytes are limited in height and generally remain small, low-growing plants.', difficulty: 'medium' },
  { id: 'pk-40', type: 'mcq', question: 'Angiosperms are considered the most successful and dominant plant group today primarily due to adaptations like:', options: ['Lack of seeds', 'Flowers, fruits, and efficient pollination/dispersal mechanisms', 'Complete absence of vascular tissue', 'Dependence entirely on water for fertilisation'], correctIndex: 1, explanation: "Flowers (enabling efficient pollination) and fruits (aiding seed dispersal) underlie the angiosperms' evolutionary success.", difficulty: 'medium' },
  { id: 'pk-41', type: 'mcq', question: 'Which of the following algae is commonly used as a source of food (as a vegetable) in some coastal regions?', options: ['Porphyra', 'Cycas', 'Pinus', 'Selaginella'], correctIndex: 0, explanation: 'Porphyra (a red alga) is consumed as food in various coastal/island cuisines.', difficulty: 'medium' },
  { id: 'pk-42', type: 'mcq', question: "Volvox and Chlamydomonas are commonly cited examples of which algal class?", options: ['Chlorophyceae', 'Phaeophyceae', 'Rhodophyceae', 'Bryophyta'], correctIndex: 0, explanation: 'Volvox and Chlamydomonas are green algae belonging to Chlorophyceae.', difficulty: 'medium' },
  { id: 'pk-43', type: 'mcq', question: 'Which of the following is generally true for the sporophyte generation in bryophytes?', options: ['It is the dominant, independent, long-lived phase', 'It is usually short-lived and remains at least partially attached to and dependent on the gametophyte', 'It never produces spores', 'It undergoes fertilisation directly'], correctIndex: 1, explanation: 'The bryophyte sporophyte is typically dependent on the gametophyte for nutrition and is comparatively short-lived.', difficulty: 'medium' },
  { id: 'pk-44', type: 'mcq', question: 'The presence of a well-developed embryo within a protective seed coat, following fertilisation, is a shared feature of:', options: ['Algae and Bryophytes only', 'Only Pteridophytes', 'Both Gymnosperms and Angiosperms', 'None of the plant groups'], correctIndex: 2, explanation: 'Both gymnosperms and angiosperms are seed plants, forming an embryo enclosed in a protective seed coat.', difficulty: 'medium' },
  { id: 'pk-45', type: 'mcq', question: "Equisetum ('horsetail') is a well-known example belonging to which plant group?", options: ['Algae', 'Bryophyta', 'Pteridophyta', 'Gymnospermae'], correctIndex: 2, explanation: 'Equisetum is a classic pteridophyte, notable for jointed, hollow stems.', difficulty: 'medium' },
  { id: 'pk-46', type: 'mcq', question: 'The term "cryptogams" traditionally refers to plant groups that:', options: ['Reproduce by visible, colourful flowers', 'Have "hidden" reproductive organs and reproduce via spores (e.g., algae, bryophytes, pteridophytes)', 'Only include gymnosperms', 'Only include angiosperms'], correctIndex: 1, explanation: "'Cryptogamae' (hidden reproduction) traditionally groups algae, bryophytes, and pteridophytes, which lack visible flower/seed structures.", difficulty: 'medium' },
  { id: 'pk-47', type: 'mcq', question: 'The term "phanerogams" traditionally refers to plant groups that:', options: ['Reproduce via spores only', 'Bear seeds, with visible reproductive organs (gymnosperms and angiosperms)', 'Lack any reproductive structures', 'Are exclusively aquatic'], correctIndex: 1, explanation: "'Phanerogamae' (visible reproduction) traditionally includes seed plants — gymnosperms and angiosperms.", difficulty: 'medium' },
  { id: 'pk-48', type: 'mcq', question: 'A characteristic feature distinguishing monocots from dicots is:', options: ['Number of cotyledons in the seed (one vs two)', 'Presence or absence of chlorophyll', 'Whether the plant is aquatic or terrestrial', 'Whether the plant reproduces sexually or asexually'], correctIndex: 0, explanation: 'The defining distinguishing feature between monocots and dicots is the number of seed cotyledons.', difficulty: 'easy' },
  { id: 'pk-49', type: 'mcq', question: 'Which of the following best explains why heterospory (as in Selaginella and seed plants) is considered evolutionarily advanced compared to homospory?', options: ['It produces fewer spores overall', 'It sets the foundation for the seed habit by allowing retention and nourishment of the megaspore leading to the embryo', 'It eliminates the need for fertilisation entirely', 'It only occurs in aquatic plants'], correctIndex: 1, explanation: 'Retaining and nourishing the megaspore is precisely the evolutionary step that eventually led to the seed habit.', difficulty: 'hard' },
  { id: 'pk-50', type: 'mcq', question: 'Which sequence correctly represents the generally accepted evolutionary trend of increasing dominance of the sporophyte generation across major plant groups?', options: ['Angiosperms → Gymnosperms → Pteridophytes → Bryophytes → Algae', 'Algae/Bryophytes (gametophyte-dominant) → Pteridophytes → Gymnosperms → Angiosperms (sporophyte-dominant)', 'There is no such general evolutionary trend across plant groups', 'Bryophytes → Algae → Angiosperms → Gymnosperms → Pteridophytes'], correctIndex: 1, explanation: 'Across plant evolution, there is a general trend from gametophyte dominance (algae/bryophytes) to increasing sporophyte dominance in higher plant groups.', difficulty: 'hard' },

  // ---- Assertion-Reason ----
  { id: 'pk-ar-1', type: 'assertion-reason', question: 'Assertion (A): Bryophytes are called amphibians of the plant kingdom.\nReason (R): They require external water for the transfer of motile male gametes to the female gametes.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'This dependence on water for fertilisation, despite living partly on land, is exactly why they earn the "amphibian" comparison.', difficulty: 'medium' },
  { id: 'pk-ar-2', type: 'assertion-reason', question: 'Assertion (A): In bryophytes, the sporophyte is the dominant, free-living phase.\nReason (R): The bryophyte sporophyte is typically small, short-lived, and remains attached to and dependent on the gametophyte.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The GAMETOPHYTE, not the sporophyte, is dominant/independent in bryophytes (A is false); R correctly describes the sporophyte\'s actual dependent nature.', difficulty: 'medium' },
  { id: 'pk-ar-3', type: 'assertion-reason', question: 'Assertion (A): Pteridophytes have a dominant sporophyte generation.\nReason (R): The pteridophyte gametophyte (prothallus) is typically small and often short-lived compared to the sporophyte.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'The relatively minor, small gametophyte compared to a large, independent sporophyte is exactly why pteridophytes are considered sporophyte-dominant.', difficulty: 'medium' },
  { id: 'pk-ar-4', type: 'assertion-reason', question: 'Assertion (A): Gymnosperms are called "naked seed" plants.\nReason (R): Their ovules/seeds are not enclosed within an ovary wall, unlike angiosperms.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'The lack of an enclosing ovary wall around the seed is exactly why gymnosperms are termed "naked seed" plants.', difficulty: 'easy' },
  { id: 'pk-ar-5', type: 'assertion-reason', question: 'Assertion (A): Double fertilisation is a feature unique to angiosperms among plants.\nReason (R): It involves the fusion of one male gamete with the egg and another with the polar nuclei, forming a zygote and endosperm respectively.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'This dual-fusion event, producing both zygote and endosperm, is exactly what defines double fertilisation as unique to angiosperms.', difficulty: 'medium' },
  { id: 'pk-ar-6', type: 'assertion-reason', question: 'Assertion (A): Heterospory is seen in all bryophytes.\nReason (R): Heterospory refers to production of two morphologically different types of spores — microspores and megaspores.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Heterospory is NOT seen in bryophytes generally — it appears in select pteridophytes (like Selaginella) and all seed plants (A is false); R correctly defines the concept itself.', difficulty: 'medium' },
  { id: 'pk-ar-7', type: 'assertion-reason', question: 'Assertion (A): A haplontic life cycle has the diploid zygote as its only diploid stage.\nReason (R): In a haplontic cycle, the zygote undergoes meiosis immediately, restoring the dominant haploid phase.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Immediate post-zygotic meiosis is exactly why the zygote remains the only diploid stage in a haplontic cycle.', difficulty: 'medium' },
  { id: 'pk-ar-8', type: 'assertion-reason', question: 'Assertion (A): Humans and most seed plants show a haplontic life cycle.\nReason (R): In these organisms, the diploid phase is the dominant, conspicuous phase, with meiosis occurring only just before gamete formation.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Such organisms actually follow a DIPLONTIC (not haplontic) life cycle (A is false); R correctly describes the diplontic pattern instead.', difficulty: 'medium' },
  { id: 'pk-ar-9', type: 'assertion-reason', question: 'Assertion (A): The male gametophyte in flowering plants is the pollen grain.\nReason (R): The pollen grain is a multicellular, free-living, independent plant capable of extended growth on its own.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: 'A is true (pollen IS the male gametophyte), but R is false — pollen grains are actually highly reduced, few-celled structures, not independent free-living plants.', difficulty: 'medium' },
  { id: 'pk-ar-10', type: 'assertion-reason', question: 'Assertion (A): Agar, a commercially important product, is extracted from certain red algae.\nReason (R): Agar is used in laboratories primarily as a solidifying agent for microbial culture media.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 1, explanation: "Both statements are true, but R describes agar's laboratory USE, not why it is extracted specifically from red algae — the two facts are related but not causally linked in this direction.", difficulty: 'medium' },
  { id: 'pk-ar-11', type: 'assertion-reason', question: 'Assertion (A): Angiosperms are considered the most evolutionarily successful and diverse plant group today.\nReason (R): Flowers and fruits provide efficient mechanisms for pollination and seed dispersal.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Efficient pollination and dispersal mechanisms via flowers/fruits are exactly what underlie the angiosperms' evolutionary success.", difficulty: 'medium' },
  { id: 'pk-ar-12', type: 'assertion-reason', question: 'Assertion (A): Bryophytes and pteridophytes both show a haplo-diplontic life cycle.\nReason (R): Both groups exhibit distinct multicellular haploid (gametophyte) and multicellular diploid (sporophyte) generations.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Having both distinct multicellular generations is exactly what defines a haplo-diplontic life cycle, applicable to both groups.', difficulty: 'medium' },
  { id: 'pk-ar-13', type: 'assertion-reason', question: 'Assertion (A): Pinus and Cycas reproduce via seeds enclosed within a fruit.\nReason (R): As gymnosperms, their ovules develop into seeds that remain exposed, not enclosed within an ovary-derived fruit.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Gymnosperm seeds are NOT enclosed in a fruit (A is false) — they remain naked, as R correctly explains.', difficulty: 'medium' },
  { id: 'pk-ar-14', type: 'assertion-reason', question: 'Assertion (A): Vascular tissue evolved to allow more efficient transport of water and nutrients over longer distances.\nReason (R): The evolution of vascular tissue in pteridophytes allowed these plants to grow taller and more complex than bryophytes.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 1, explanation: 'Both statements are true and related, but R describes a downstream CONSEQUENCE (increased height/complexity) rather than directly explaining why vascular tissue evolved for transport efficiency in the first place.', difficulty: 'hard' },
  { id: 'pk-ar-15', type: 'assertion-reason', question: 'Assertion (A): The endosperm formed in angiosperms after double fertilisation is always diploid, like the zygote.\nReason (R): The endosperm forms from the fusion of one male gamete with two polar nuclei, making it triploid.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The endosperm is actually TRIPLOID, not diploid like the zygote (A is false); R correctly explains why it ends up triploid.', difficulty: 'medium' },
  { id: 'pk-ar-16', type: 'assertion-reason', question: 'Assertion (A): Selaginella is an example of a homosporous pteridophyte.\nReason (R): Selaginella actually produces two distinct types of spores — microspores and megaspores.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Selaginella is actually HETEROSPOROUS, not homosporous (A is false); R correctly describes its two distinct spore types.', difficulty: 'medium' },
  { id: 'pk-ar-17', type: 'assertion-reason', question: 'Assertion (A): Chlorophyceae members store their reserve food material mainly as starch.\nReason (R): Chlorophyceae members possess chlorophyll a and b as their dominant photosynthetic pigments, similar to higher plants.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 1, explanation: 'Both statements are true, but the pigment composition (R) does not directly explain the type of stored food (starch) — these are two separate, coincidentally shared characteristics with higher plants.', difficulty: 'hard' },
  { id: 'pk-ar-18', type: 'assertion-reason', question: 'Assertion (A): The seed habit provides significant survival advantages over spore dispersal.\nReason (R): Seeds contain a protected, nourished embryo capable of surviving unfavourable conditions until germination.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'This built-in protection and nourishment is exactly what gives seeds their survival advantage over bare spores.', difficulty: 'medium' },
  { id: 'pk-ar-19', type: 'assertion-reason', question: 'Assertion (A): Cycas is monoecious, bearing both male and female reproductive structures on the same plant.\nReason (R): Cycas is dioecious, with separate male and female plants.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Cycas is actually dioecious (A is false, since it claims the opposite — monoecious); R correctly states that Cycas has separate male and female plants.', difficulty: 'medium' },
  { id: 'pk-ar-20', type: 'assertion-reason', question: 'Assertion (A): Monocots and dicots are distinguished based on the number of cotyledons present in the seed.\nReason (R): Monocots have one cotyledon, while dicots have two.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "The specific one-vs-two cotyledon distinction directly explains and defines the monocot/dicot classification.", difficulty: 'easy' },

  // ---- Statement-based ----
  { id: 'pk-st-1', type: 'statement', question: 'Statement I: Algae are classified largely based on the type of pigments and stored food they contain.\nStatement II: All algae are terrestrial and have no aquatic representatives.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — algae are predominantly aquatic, not terrestrial.', difficulty: 'medium' },
  { id: 'pk-st-2', type: 'statement', question: 'Statement I: Bryophytes require water for fertilisation.\nStatement II: Bryophytes have well-developed vascular tissue for efficient water transport.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — bryophytes lack true vascular tissue.', difficulty: 'medium' },
  { id: 'pk-st-3', type: 'statement', question: 'Statement I: In pteridophytes, the sporophyte is dominant and independent.\nStatement II: The pteridophyte gametophyte is called the prothallus.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe key features of the pteridophyte life cycle.', difficulty: 'medium' },
  { id: 'pk-st-4', type: 'statement', question: 'Statement I: Gymnosperm seeds are enclosed within a fruit.\nStatement II: Angiosperm seeds are enclosed within a fruit.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — gymnosperm seeds are naked, not fruit-enclosed; Statement II correctly describes angiosperm seeds.', difficulty: 'medium' },
  { id: 'pk-st-5', type: 'statement', question: 'Statement I: Double fertilisation occurs in both gymnosperms and angiosperms.\nStatement II: Double fertilisation is a defining, unique feature of angiosperms.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — gymnosperms do not undergo double fertilisation; Statement II correctly identifies it as unique to angiosperms.', difficulty: 'medium' },
  { id: 'pk-st-6', type: 'statement', question: 'Statement I: A haplontic life cycle has the zygote as the only diploid stage.\nStatement II: A diplontic life cycle has the gametes as the only haploid stage.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the defining features of haplontic and diplontic life cycles respectively.', difficulty: 'medium' },
  { id: 'pk-st-7', type: 'statement', question: 'Statement I: Chlorophyceae members are commonly known as green algae.\nStatement II: Rhodophyceae members are commonly known as brown algae.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — Rhodophyceae are red algae, not brown (Phaeophyceae are the brown algae).', difficulty: 'medium' },
  { id: 'pk-st-8', type: 'statement', question: 'Statement I: Heterospory is seen in Selaginella, a pteridophyte.\nStatement II: Heterospory is seen in all seed plants (gymnosperms and angiosperms).', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly identify examples/groups where heterospory occurs.', difficulty: 'medium' },
  { id: 'pk-st-9', type: 'statement', question: 'Statement I: The pollen grain is the female gametophyte in flowering plants.\nStatement II: The embryo sac is the female gametophyte in flowering plants.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the pollen grain is the MALE gametophyte; Statement II correctly identifies the embryo sac as female.', difficulty: 'medium' },
  { id: 'pk-st-10', type: 'statement', question: 'Statement I: Bryophytes include liverworts, mosses, and hornworts.\nStatement II: Pteridophytes include ferns, Selaginella, and Equisetum.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly list representative examples of their respective plant groups.', difficulty: 'easy' },
  { id: 'pk-st-11', type: 'statement', question: 'Statement I: Agar and algin are commercially useful products derived from algae.\nStatement II: These products are used mainly as building construction materials.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — agar and algin are used in labs/food industries, not construction.', difficulty: 'medium' },
  { id: 'pk-st-12', type: 'statement', question: 'Statement I: Cycas and Pinus are examples of angiosperms.\nStatement II: Cycas and Pinus are examples of gymnosperms.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — Cycas and Pinus are gymnosperms, not angiosperms; Statement II correctly classifies them.', difficulty: 'easy' },
  { id: 'pk-st-13', type: 'statement', question: 'Statement I: The endosperm in angiosperms is triploid.\nStatement II: The endosperm provides nourishment to the developing embryo.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the ploidy and function of the angiosperm endosperm.', difficulty: 'medium' },
  { id: 'pk-st-14', type: 'statement', question: 'Statement I: A protonema is a filamentous stage seen during moss development.\nStatement II: A prothallus is a filamentous stage seen during fern (pteridophyte) development.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is inaccurate as commonly described — the prothallus is generally a small, flattened, heart-shaped structure, not typically described as filamentous like the protonema.', difficulty: 'hard' },
  { id: 'pk-st-15', type: 'statement', question: 'Statement I: The vascular tissue system first became prominent in pteridophytes.\nStatement II: Bryophytes possess a fully developed vascular tissue system similar to pteridophytes.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — bryophytes lack the well-developed vascular tissue seen in pteridophytes.', difficulty: 'medium' },
  { id: 'pk-st-16', type: 'statement', question: 'Statement I: Monocot seeds have two cotyledons.\nStatement II: Dicot seeds have two cotyledons.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — monocots have ONE cotyledon; Statement II correctly describes dicots.', difficulty: 'easy' },
  { id: 'pk-st-17', type: 'statement', question: 'Statement I: Chlorella and Spirulina are cultivated as sources of single-cell protein.\nStatement II: These algae are entirely non-nutritious and provide no dietary value.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — these algae are valued precisely for their high nutritional/protein content.', difficulty: 'medium' },
  { id: 'pk-st-18', type: 'statement', question: 'Statement I: The seed habit evolved as an adaptation providing better protection and nourishment for the embryo.\nStatement II: Heterospory is considered a step toward the evolution of the seed habit.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the evolutionary significance of the seed habit and its connection to heterospory.', difficulty: 'medium' },
  { id: 'pk-st-19', type: 'statement', question: 'Statement I: All plant groups show exactly the same type of life cycle pattern (haplontic, diplontic, or haplo-diplontic).\nStatement II: Different plant groups can show different life cycle patterns — e.g., some algae are haplontic while seed plants are diplontic.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — life cycle patterns vary considerably across plant groups; Statement II correctly reflects this diversity.', difficulty: 'medium' },
  { id: 'pk-st-20', type: 'statement', question: "Statement I: Angiosperms are generally considered more evolutionarily advanced than gymnosperms.\nStatement II: This is largely attributed to features like flowers, fruits, and double fertilisation.", options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements are correct and connected — these angiosperm-specific features underpin their advanced evolutionary status.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'pk-hm-1', type: 'statement', question: 'How many of the following are classes of algae based on pigmentation?\nChlorophyceae, Phaeophyceae, Rhodophyceae, Bryophyceae', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Chlorophyceae, Phaeophyceae, and Rhodophyceae are the three algal classes; "Bryophyceae" is not a recognised group.', difficulty: 'medium' },
  { id: 'pk-hm-2', type: 'statement', question: 'How many of the following are considered "cryptogams" (spore-producing, without true seeds)?\nAlgae, Bryophytes, Pteridophytes, Gymnosperms', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Algae, bryophytes, and pteridophytes are cryptogams; gymnosperms are seed plants (phanerogams).', difficulty: 'medium' },
  { id: 'pk-hm-3', type: 'statement', question: 'How many of the following are considered "phanerogams" (seed-producing plants)?\nGymnosperms, Angiosperms, Bryophytes, Pteridophytes', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Gymnosperms and angiosperms are phanerogams (seed plants); bryophytes and pteridophytes are cryptogams.', difficulty: 'medium' },
  { id: 'pk-hm-4', type: 'statement', question: 'How many of the following features are correctly associated with bryophytes?\nDominant gametophyte generation, Dependence on water for fertilisation, Well-developed vascular tissue, A short-lived, dependent sporophyte', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Dominant gametophyte, water dependence, and a short-lived sporophyte are all correct bryophyte features; they lack well-developed vascular tissue.', difficulty: 'medium' },
  { id: 'pk-hm-5', type: 'statement', question: 'How many of the following are examples of pteridophytes?\nFerns, Selaginella, Equisetum, Cycas', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Ferns, Selaginella, and Equisetum are pteridophytes; Cycas is a gymnosperm.', difficulty: 'medium' },
  { id: 'pk-hm-6', type: 'statement', question: 'How many of the following are true regarding double fertilisation in angiosperms?\nOne male gamete fuses with the egg to form the zygote, Another male gamete fuses with polar nuclei to form the endosperm, The endosperm is triploid, This process also occurs in gymnosperms', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements correctly describe double fertilisation in angiosperms; it does NOT occur in gymnosperms.', difficulty: 'medium' },
  { id: 'pk-hm-7', type: 'statement', question: 'How many of the following are types of plant life cycle patterns?\nHaplontic, Diplontic, Haplo-diplontic, Triplontic', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Haplontic, diplontic, and haplo-diplontic are the three recognised life cycle patterns; "triplontic" is not a real category.', difficulty: 'medium' },
  { id: 'pk-hm-8', type: 'statement', question: 'How many of the following commercially important products are correctly matched to their algal source?\nAgar from red algae, Algin from brown algae, Single-cell protein from Chlorella/Spirulina, Rubber latex from green algae', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three are correctly matched; rubber latex comes from certain flowering plants (like Hevea), not algae.', difficulty: 'medium' },
  { id: 'pk-hm-9', type: 'statement', question: 'How many of the following are features generally associated with gymnosperms?\nNaked seeds, Reduced, sporophyte-dependent gametophytes, Fertilisation typically via pollen tube, Seeds enclosed within a fruit', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Naked seeds, reduced gametophytes, and pollen-tube fertilisation are correct gymnosperm features; fruit-enclosed seeds are an angiosperm feature.', difficulty: 'medium' },
  { id: 'pk-hm-10', type: 'statement', question: 'How many of the following are correctly considered advantages of the seed habit over spore-based reproduction?\nProtection of the embryo by a seed coat, Stored food reserves supporting early growth, Improved dispersal potential, Complete elimination of the need for pollination', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Protection, stored food, and improved dispersal are genuine advantages of seeds; pollination is still required in seed plants, so that statement is incorrect.', difficulty: 'medium' },
];
